```javascript
// aws-secrets.js
const AWS = require('aws-sdk');

class SecureSecretsManager {
  constructor() {
    this.secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTtl = 300000; // 5 minutes
  }

  async getSecret(secretName) {
    const now = Date.now();
    const cached = this.cache.get(secretName);

    // Return cached secret if it exists and hasn't expired
    if (cached && (now - cached.timestamp) < this.cacheTtl) {
      return cached.value;
    }

    try {
      const data = await this.secretsManager.getSecretValue({ SecretId: secretName }).promise();
      let secretValue;

      if (data.SecretString) {
        secretValue = data.SecretString;
      } else {
        const buff = Buffer.from(data.SecretBinary, 'base64');
        secretValue = buff.toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: now
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret ${secretName}:`, error);
      throw error;
    }
  }

  // Bulk load secrets
  async loadSecrets(secretNames) {
    const secrets = {};
    const promises = secretNames.map(async (name) => {
      secrets[name] = await this.getSecret(name);
    });

    await Promise.all(promises);
    return secrets;
  }
}

module.exports = SecureSecretsManager;
```

