      return response.data;
    } catch (error) {
      console.error(`Vault read error for ${path}:`, error);
      throw error;
    }
  }

  async renewToken() {
    try {
      await this.vault.write('auth/token/renew-self');
    } catch (error) {
      console.error('Token renewal failed:', error);
    }
  }
}
```

