    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    },
  },
}));
```

### 2. Insecure HTTP Methods

**Issue**: The application doesn't restrict HTTP methods, potentially allowing unintended operations.

**Recommendation**: Explicitly define allowed methods and block others.

```javascript
// Restrict endpoints to specific methods
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
